function isSpm(){return state.page.startsWith('spm-')}
function spmParent(page){return spmMenu.find(m=>m[3]?.some(x=>x[1]===page))?.[0]||''}
function spmNav(){return spmMenu.map(m=>`<div class="menu-group"><button class="menu-main ${state.page===m[1]||m[3]?.some(x=>x[1]===state.page)?'active':''}" data-nav="${m[1]||''}" data-group="${m[0]}"><span class="icon">${m[2]}</span><span>${m[0]}</span>${m[3]?'<span class="chev">'+(state.open===m[0]?'⌄':'›')+'</span>':''}</button>${m[3]&&state.open===m[0]?`<div class="submenu">${m[3].map(([label,id])=>`<button class="${state.page===id?'active':''}" data-nav="${id}">${label}</button>`).join('')}</div>`:''}</div>`).join('')}
