function spmRiskVectors(){const weights=[['受駭系統',26],['重大弱點管理',20],['SSL 設定',15],['SSL 憑證',10],['開放連接埠',10],['Web 應用程式安全',5],['桌面軟體',3],['檔案分享',2.5],['不安全系統',2.5],['伺服器軟體',2],['其他',4]];return `${pagebar('Saperix, Inc. 風險面向總覽','<button class="outline" data-modal="reports">報表　▧</button><button class="outline" data-modal="spm-action">動作　⌄</button>')}<div class="risk-vector-layout"><aside class="risk-vector-nav"><button class="rv-overview active">總覽　‹</button>${riskGroups.map(([group,total,items])=>`<section><h4>${group}</h4><b>${total}</b>${items.map(([name,w,g])=>`<button data-rv="${name}"><span>${name}<small>權重：${w}</small></span><i class="${gradeClass(g)}">${g}</i></button>`).join('')}</section>`).join('')}</aside><main class="risk-vector-main"><section class="panel rv-intro"><h2>總覽</h2><h3>關於風險面向與類別</h3><div class="rv-intro-grid"><p>了解風險面向、類別及本頁的運作方式，有助於安排資源優先順序，並對安全評等產生最大正面影響。改善工作應優先處理權重最高的風險類別與相關面向。<br><br><a>Bitsight 安全評等</a>會每日依專有演算法計算，用來評估組織的資安成效。</p><ul>${weights.map(([n,w])=>`<li><i></i><b>${w}%</b> ${n}</li>`).join('')}</ul><div class="rv-donut"><span>影響評等的<br>風險面向權重</span></div></div></section>${riskGroups.map(([group,total,items])=>`<section class="panel rv-group"><h2>${group}</h2><div class="rv-cards">${items.map(([name,w,g],i)=>`<article><i class="${gradeClass(g)}">${g}</i><div><h3>${name}　<a>#</a></h3><span>${g==='A'?'前 10%':g==='B'?'前 30%':g==='C'?'前 50%':g==='D'?'後 30%':g==='F'?'後 20%':'無評級'}</span></div><button data-nav="spm-findings">查看發現事項</button></article>`).join('')}</div></section>`).join('')}</main></div>`}
function rvGrade(g){return `<i class="rv2-grade ${gradeClass(g)}">${g}</i>`}
function rvNav(){return `<aside class="rv2-nav"><button class="rv2-overview">總覽 <span>‹</span></button><div class="rv2-nav-scroll">${riskGroups.map(([group,total,items])=>`<section><h3>${group}</h3><b>${total}</b>${items.map(([name,w,g])=>`<button><span>${name}<small>${w.includes('不影響')?'不影響評等':'權重：'+w}</small></span>${rvGrade(g)}</button>`).join('')}</section>`).join('')}</div></aside>`}
function rvOverview(){const weights=[['26%','受駭系統'],['20%','重大弱點管理'],['15%','TLS/SSL 設定'],['10%','TLS/SSL 憑證'],['10%','開放連接埠'],['5%','Web 應用程式安全'],['3%','桌面軟體'],['2.5%','檔案分享'],['2.5%','不安全系統'],['2%','伺服器軟體'],['4%','其他']];return `<section class="panel rv2-overview-card"><h2>總覽</h2><h3>關於風險面向與類別</h3><div class="rv2-overview-body"><p>了解風險面向、類別及本頁的運作方式，有助於安排資源優先順序，並對評等產生最大的正面影響。改善工作應配合對安全評等貢獻最高的風險類別及相關面向。<br><br><a>Bitsight 安全評等</a>會使用專有演算法每日產生並計算，用以評估組織的資安成效。右側圖表顯示主要風險面向及其在 Bitsight 評等中的權重百分比。</p><ul>${weights.map(x=>`<li><i></i><b>${x[0]}</b> ${x[1]}</li>`).join('')}</ul><div class="rv2-donut"><span>影響評等的<br>風險面向權重</span></div></div></section>`}
function rvBubbleChart(){const dots=[[65,108,10],[118,165,7],[172,135,9],[230,190,7],[285,145,11],[345,215,8],[405,168,10],[466,235,7],[528,185,12],[592,220,8],[648,155,10],[710,205,7]];return `<div class="rv2-bubble"><header><h3>過去 12 個月的事件</h3><label>納入不影響評等的發現事項　<input type="checkbox"></label></header><svg viewBox="0 0 760 260"><g stroke="#d8e1e6" stroke-dasharray="4 4">${[35,80,125,170,215].map(y=>`<line x1="35" y1="${y}" x2="745" y2="${y}"/>`).join('')}</g>${dots.map(([x,y,r],i)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${['#347da6','#d16a54','#66a66e','#8f6fb0','#d8ad42'][i%5]}" opacity=".9"/>`).join('')}<g fill="#526a78" font-size="11">${['9 月','10 月','11 月','12 月','1 月','2 月','3 月','4 月','5 月','6 月','7 月','8 月'].map((m,i)=>`<text x="${45+i*60}" y="252">${m}</text>`).join('')}</g></svg><div class="rv2-chart-legend"><span>● 殭屍網路感染</span><span>● 垃圾郵件傳播</span><span>● 惡意程式伺服器</span><span>● 未經請求的通訊</span><span>● 可能遭到利用</span></div></div>`}
function rvExpanded(name,g,rank,desc,a,b){return `<article class="rv2-expanded"><header>${rvGrade(g)}<h3>${name}　<a>#</a><small>${rank}</small></h3></header><div class="rv2-expanded-body"><p>${desc}</p><a>檢視發現事項</a>　<a>更多資訊</a><div class="rv2-compare"><section><h4>過去一年的事件數</h4><b>${a}% 少於科技業</b><i><span style="width:${a}%"></span></i><small>Saperix, Inc.　　　　科技業</small></section><section><h4>過去一年解決事件的平均天數</h4><b>${b}% 快於科技業</b><i><span style="width:${b}%"></span></i><small>Saperix, Inc.　　　　科技業</small></section></div></div></article>`}
const compromisedMetrics={
 '殭屍網路感染':['C','前 50%',25,151,'83.44% 少於科技業',1.2,3.0,'60% 快於科技業'],
 '垃圾郵件傳播':['D','後 30%',32,45,'28.89% 少於科技業',2.0,1.2,'66.67% 慢於科技業'],
 '惡意程式伺服器':['A','前 10%',0,7,'科技業比較期間內未偵測到事件',0,2.4,'解決時間優於科技業'],
 '未經請求的通訊':['A','前 10%',0,12,'科技業比較期間內未偵測到事件',0,1.8,'解決時間優於科技業'],
 '可能遭到利用':['C','前 50%',22,56,'60.71% 少於科技業',1.7,2.6,'34.62% 快於科技業']};
function rvHorizontalChart(title,note,company,industry,unit=''){const max=Math.max(company,industry,1);return `<section class="rv-h-chart"><h4>${title}</h4><p>${note}</p><div class="rv-h-grid"><b>Saperix, Inc.</b><i><span class="company" style="width:${company/max*88}%"></span><em>${company}${unit}</em></i><b>科技業</b><i><span class="industry" style="width:${industry/max*88}%"></span><em>${industry}${unit}</em></i></div><div class="rv-h-axis"><span>0</span><span>${Math.round(max*.25*10)/10}</span><span>${Math.round(max*.5*10)/10}</span><span>${Math.round(max*.75*10)/10}</span><span>${max}</span></div></section>`}
function rvCompromisedVector(name){const [g,rank,events,industryEvents,eventNote,days,industryDays,dayNote]=compromisedMetrics[name];return `<article class="rv-comp-vector"><header>${rvGrade(g)}<h3>${name}　<a>🔗</a></h3><b>↗ ${rank}</b></header><div class="rv-comp-body"><aside><p>${rvDescriptions[name]||'此風險面向顯示公司網路中觀察到的受駭活動及其可能影響。'}</p><button>▦　檢視發現事項</button><a>▣　更多資訊</a></aside><main>${rvHorizontalChart('過去一年的事件數',eventNote,events,industryEvents)}${rvHorizontalChart('過去一年解決事件的平均天數',dayNote,days,industryDays,' 天')}</main></div></article>`}
const rvDescriptions={
 '殭屍網路感染':'殭屍網路感染事件表示公司網路中的裝置被觀察到以殭屍主機或命令與控制伺服器的身分參與殭屍網路。殭屍網路可用於竊取公司機密與敏感客戶資訊、將公司資源轉作非法用途，並成為其他感染的傳播管道。',
 '垃圾郵件傳播':'當公司網路中的裝置正在傳送未經請求的商業郵件或大量電子郵件時，就會出現垃圾郵件傳播事件。這類活動可能損害公司聲譽，並使合法的公司郵件遭垃圾郵件篩選器攔截。',
 '惡意程式伺服器':'當伺服器被觀察到從事惡意活動，例如託管網路釣魚、詐騙或欺詐網站時，就會出現惡意程式伺服器事件。受駭伺服器可能感染連線至公司資源的裝置，使員工與客戶面臨風險。',
 '未經請求的通訊':'當裝置嘗試與未提供任何有效服務的伺服器通訊時，就會出現未經請求的通訊事件。這類活動不僅顯示裝置已遭入侵，也表示裝置正主動尋找其他可感染的裝置。','可能遭到利用':'當公司網路中的瀏覽器感染會改變使用者體驗的惡意軟體（例如廣告軟體）時，就會出現可能遭到利用事件。這類事件通常也代表可能存在其他感染。',
 'SPF 網域':'評估網域是否正確設定 SPF，以降低電子郵件偽冒風險。','DKIM 記錄':'評估電子郵件是否使用 DKIM 簽章來驗證郵件來源。','DMARC':'評估網域是否使用 DMARC 政策防止電子郵件冒用。',
 'TLS/SSL 憑證':'評估公開服務使用的 TLS/SSL 憑證是否有效、安全且正確部署。','TLS/SSL 設定':'評估伺服器的加密協定與密碼套件是否符合安全實務。','開放連接埠':'識別可從網際網路存取、可能增加攻擊面的網路服務。',
 'Web 應用程式安全':'評估公開網站與 Web 應用程式中的安全設定與常見弱點。','重大弱點管理':'衡量組織修補高風險與已知遭利用弱點的速度。','不安全系統':'識別使用過時、停止支援或具有高風險設定的系統。',
 '伺服器軟體':'評估對外伺服器軟體的版本、支援狀態與已知弱點。','桌面軟體':'評估終端裝置桌面軟體的版本與安全更新狀態。','行動軟體':'評估行動裝置軟體與應用程式的更新和安全狀態。',
 'DNSSEC*':'顯示網域是否使用 DNSSEC 保護 DNS 回應的完整性。','Web 應用程式標頭*':'檢查 Web 應用程式是否設定建議的 HTTP 安全標頭。','網域仿冒**':'識別可能冒用公司品牌、網域或商標的相似網域。',
 '檔案分享':'識別可能透過點對點檔案分享服務暴露資料的活動。','外洩憑證**':'顯示在公開資料來源中發現、可能與組織相關的外洩帳號。',
 '資安事件／資料外洩':'彙整已公開揭露且可能影響安全評等的資安事件與資料外洩。','其他揭露*':'顯示其他公開揭露、執法或監管相關的資安資訊。'};
function rvPercentile(g){return g==='A'?'前 10%':g==='B'?'前 30%':g==='C'?'前 50%':g==='D'?'後 30%':g==='F'?'後 20%':'無評級'}
function rvFullVector(name,g,index){const na=g==='N/A',v1=18+(index*13)%68,v2=24+(index*17)%64;return `<article class="rv2-full-vector"><header>${rvGrade(g)}<h3>${name}　<a>#</a><small>${rvPercentile(g)}</small></h3></header><p>${rvDescriptions[name]||'此風險面向呈現組織目前的安全成效與可改善項目。'}</p><p><a>檢視發現事項</a>　<a>更多資訊</a></p>${na?`<div class="rv2-na-note">此資訊型風險面向目前不影響 Bitsight 安全評等。</div>`:`<div class="rv2-vector-charts"><section><h4>過去一年觀察到的紀錄</h4><b>${v1}% 優於科技業</b><div class="rv2-bars"><span style="height:${v1}%"><i>Saperix</i></span><span style="height:${Math.min(96,v1+24)}%"><i>科技業</i></span></div></section><section><h4>最近 60 天的成效分布</h4><b>${v2}% 符合良好標準</b><div class="rv2-stack"><i style="width:${v2}%"></i><i style="width:${Math.max(8,70-v2)}%"></i><i></i></div><small>良好　　普通　　不佳</small></section></div>`}</article>`}
function rvDiligenceOverview(){const months=['2026 年 3 月','2026 年 4 月','2026 年 5 月','2026 年 6 月','2026 年 7 月','2026 年 8 月','目前'];return `<div class="rv-diligence-overview"><p>盡職調查風險面向顯示公司為防止攻擊所採取的措施。Bitsight 目前會評估 SPF、DKIM、TLS/SSL、開放連接埠及 DNSSEC 資訊，以判定公司的安全盡職調查成效。</p><p>所有盡職調查紀錄會評估為良好、普通、警告、不佳或中性，並依產業標準判定。每項盡職調查風險面向的整體字母等級，會依各筆紀錄的評估結果計算。</p><p>例如，公司若有三個網域且皆設定有效 SPF 紀錄，整體 SPF 等級將為 A；若三個網域都沒有 SPF 紀錄，則整體等級為 F。</p><div class="rv-diligence-tools"><label>檢視方式 <select><option>所有盡職調查風險面向</option></select></label><div><button class="active">百分比</button><button>數量</button></div><span class="spacer"></span><button>↗ ▥</button><button>⇩</button></div><div class="rv-diligence-chart"><div class="rv-diligence-legend"><label><input checked type="checkbox"> 良好</label><label><input checked type="checkbox"> 普通</label><label><input checked type="checkbox"> 警告</label><label><input checked type="checkbox"> 不佳</label><label><input type="checkbox"> 中性</label></div><div class="rv-area-axis"><span>100%</span><span>75%</span><span>50%</span><span>25%</span><span>0%</span></div><div class="rv-area-columns">${months.map((m,i)=>`<div><i class="good-area" style="height:${78-i*.5}%"></i><i class="fair-area" style="height:${2+i*.3}%"></i><i class="warn-area" style="height:${4-i*.15}%"></i><i class="bad-area" style="height:${16+i*.35}%"></i><b>${m}</b></div>`).join('')}</div><strong class="rv-area-title">紀錄分布</strong></div></div>`}
const diligenceDistribution={
 'SPF 網域':[9,[77.8,0,0,22.2,0]],'DKIM 記錄':[9,[55.6,0,0,44.4,0]],'DMARC':[9,[66.7,11.1,0,22.2,0]],
 'TLS/SSL 憑證':[8241,[69,4,3,17,7]],'TLS/SSL 設定':[8018,[31,2,4,58,5]],'開放連接埠':[15742,[38,3,5,46,8]],'Web 應用程式安全':[85,[22.4,47.1,8.2,2.4,20],'項發現事項'],'不安全系統':[5,[0,0,100,0,0]],'伺服器軟體':[726,[6.7,.4,7.2,5.1,80.6]],'桌面軟體':[340,[49.7,7.1,39.7,3.5,0],'位使用者'],'行動軟體':[78,[35.9,17.9,21.8,0,24.4],'位使用者'],'DNSSEC*':[14,[0,0,0,0,100]],'Web 應用程式標頭*':[0,[0,0,0,0,0]]};
const diligenceExplain={'SPF 網域':'正確設定的 SPF 紀錄可向接收郵件伺服器提供拒絕未授權主機郵件所需的資訊，確保只有獲授權的主機能代表公司寄送電子郵件。Bitsight 會確認所有正在寄送或曾嘗試寄送郵件的網域均設有 SPF 紀錄，並確認其設定可協助防止電子郵件偽冒。','DKIM 記錄':'正確設定的 DKIM 紀錄可協助確保只有獲授權的主機能代表公司寄送電子郵件。Bitsight 會確認公司使用 DKIM，且其設定方式能防止電子郵件偽冒。','DMARC':'DMARC 會驗證電子郵件寄件者是否確實獲授權代表公司寄送郵件，提供防範電子郵件偽冒的保護。','TLS/SSL 憑證':'TLS/SSL 憑證用於加密網際網路流量。Bitsight 會分析 TLS/SSL 憑證並提供其有效性資訊。憑證負責向合作夥伴、客戶與訪客驗證公司伺服器的真實身分，也是建立密碼學信任的基礎。','TLS/SSL 設定':'評估 TLS/SSL 伺服器設定，包括公司伺服器是否正確設定安全通訊協定函式庫，以及在與其他機器建立加密連線時是否支援強式加密標準。錯誤或薄弱的設定可能使伺服器暴露於 POODLE、Heartbleed 等攻擊。','開放連接埠':'開放連接埠會顯示哪些連接埠號碼與服務暴露於網際網路。部分連接埠必須開放以支援正常業務功能，但不必要的開放連接埠也會為攻擊者提供存取公司網路的途徑。','Web 應用程式安全':'此風險面向會執行多種與 Web 應用程式安全相關的評估，提供已知弱點元件、失效的驗證與存取控制、敏感資料暴露、跨網站指令碼防護機制及安全設定錯誤等資訊。','不安全系統':'不安全系統表示組織端點正在與非預期目的地通訊。這些端點的軟體可能已過時、遭竄改或設定錯誤。「端點」包括任何可存取網際網路的桌上型電腦、伺服器、行動裝置、媒體系統或設備。當端點嘗試與尚不存在或未註冊給任何人的網域通訊時，該系統就會被分類為「不安全系統」。','伺服器軟體':'伺服器軟體風險類型可建立組織所用軟體的完整概況，並協助追蹤因伺服器軟體已不再受原始開發者支援或已過時（棄用）而產生的安全缺口。','桌面軟體':'桌面軟體包括公司網路中可存取網際網路的筆記型電腦、伺服器及其他非平板、非手機電腦。桌面軟體的對外通訊包含裝置作業系統與瀏覽器版本的中繼資料；Bitsight 會將裝置的作業系統及瀏覽器版本與目前發布版本及可用軟體更新比較，判定系統仍受支援或已過時。','行動軟體':'行動軟體衡量從組織網路存取網際網路的智慧型手機、平板等行動裝置。行動裝置的對外通訊包含作業系統、瀏覽器版本及應用程式的中繼資料；Bitsight 會將版本資訊與目前最新可用版本比較，判定裝置執行的軟體仍受支援或已過時。','DNSSEC*':'DNSSEC 是使用公開金鑰加密驗證 DNS 伺服器的通訊協定。Bitsight 會確認公司是否使用 DNSSEC，以及其設定是否有效。','Web 應用程式標頭*':'此風險面向分析 HTTP 請求與回應訊息標頭區段中的安全相關欄位。若設定正確，這些欄位可協助防範惡意行為，包括中間人攻擊與跨網站指令碼攻擊。HTTP/1.0、HTTP/1.1 與 HTTPS 各自需要不同類型的標頭；可參閱知識庫了解各通訊協定所需的標頭清單。'};
function rvRankChart(title,rows,color='#07517f'){const max=Math.max(...rows.map(x=>x[1]));return `<section class="rv-rank"><h4>${title}</h4>${rows.map(([n,v])=>`<div><b>${n}</b><i style="width:${v/max*78}%;background:${color}"></i><strong>${v}</strong></div>`).join('')}</section>`}
function rvThresholdChart(kind,points,max){return `<section class="rv-desktop-wide"><h4>${kind}：裝置總數與門檻</h4><p>以下為過去六個月觀察到的裝置，顯示其何時開始影響${kind}風險面向等級。發現事項必須達到門檻並持續高於門檻 65 天，才會影響評等。</p><div class="rv-threshold" style="--max:${max}">${points.map(([m,v],i)=>`<i style="left:${8+i*17}%;bottom:${v/max*82}%"><b>${m}</b></i>`).join('')}<span>門檻：5</span></div><strong class="rv-axis-caption">過去六個月　　● 觀察到的裝置</strong></section>`}
function rvTimeline(title,names,mobile=false){return `<section class="rv-desktop-wide"><h4>${title}：未來六個月發現事項等級演變</h4><p>依嚴重程度及距離過時的時間排序，顯示未來六個月的變化。</p><label><input checked type="checkbox"> 作業系統　 <input checked type="checkbox"> 瀏覽器</label><div class="rv-timeline ${mobile?'mobile':''}">${names.map((x,i)=>`<div><b>${x}</b><i><span style="left:${i<2?0:Math.min(98,(i-1)*14)}%"></span></i></div>`).join('')}</div><strong class="rv-axis-caption">10 月　　11 月　　12 月　　1 月　　2 月　　3 月</strong></section>`}
function rvSoftwareExtras(name){if(name==='伺服器軟體'){const types=[['Apache',166],['nginx',163],['OpenSSH',163],['MS IIS',50],['OpenSSH',43],['PHP',36],['nginx',34],['OpenSSH',25],['OpenSSH',11],['MS IIS',7]],vers=[['nginx nginx',126],['Apache',114],['MS IIS 10.0',50],['OpenSSH 9.6p1',40],['OpenSSH 8.9p1',30],['OpenSSH 8.0',28],['nginx 1.18.0',23],['OpenSSH 7.4',22],['OpenSSH 8.2p1',15],['Apache 2.4.58',13]];return `<div class="rv-software-pairs">${rvRankChart('主要軟體類型',types)}${rvRankChart('主要軟體版本',vers)}</div>`}const desktop=name==='桌面軟體';if(desktop||name==='行動軟體'){const old=desktop?[['Chrome 145',57],['Firefox 145',31],['Edge 145',25],['Edge 151',20],['Chrome 96.0.4664',10],['Firefox 128',9],['Chrome 142',2],['Chrome 146',2],['Chrome 148',2],['Chrome 150',2]]:[['Chrome Mobile iOS 145',15],['iOS 26.2.1',8],['iOS 26.5',5],['iOS 26.3',4],['iOS 18.6.1',2],['iOS 26.3.1',2],['iOS 26.5.2',2],['iOS 26.6',2],['Mobile Safari 18.6',2],['iOS 18.5',1]],timeline=desktop?['Chrome 96.0.4664','Firefox 128','Mac OS X 10.15','Safari 17.5','Firefox 115','Chrome 142','Firefox 145','Chrome 145','Edge 144','Edge 145']:['iOS 18.5','iOS 18.6.1','Chrome Mobile iOS 142','iOS 26.2','iOS 26.2.1','Chrome Mobile iOS 145','iOS 26.3','Chrome Mobile iOS 149','Chrome Mobile iOS 150','iOS 26.3.1'],pts=desktop?[['4 月',190],['5 月',195],['6 月',140],['7 月',112],['8 月',422],['9 月',341]]:[['4 月',112],['5 月',97],['6 月',53],['7 月',66],['8 月',54],['9 月',59]],kind=desktop?'桌面軟體':'行動軟體';return `<aside class="rv-tip"><h4>提示　💡</h4><p>若組織設有訪客網路，請聯絡 Bitsight 支援團隊，申請將其排除於影響評等的基礎設施之外。</p></aside><section class="rv-desktop-wide"><h4>已過時的主要${kind}</h4><p>最多顯示 10 個已達生命週期終點的作業系統與瀏覽器。</p><label><input checked type="checkbox"> 作業系統　 <input checked type="checkbox"> 瀏覽器</label>${rvRankChart('',old,'#e76f3d')}</section>${rvTimeline(kind,timeline,!desktop)}${rvThresholdChart(kind,pts,desktop?500:140)}`}return ''}
function rvGradeDistribution(name,g){const [count,vals,unit='筆紀錄']=diligenceDistribution[name],cats=['良好','普通','警告','不佳','中性'],colors=['#2db37d','#dda91e','#e56d3a','#df4435','#58758a'],info=name.endsWith('*');return `<article class="rv-grade-section"><header>${rvGrade(g)}<h3>${name}　<a>🔗</a><small>${rvPercentile(g)}</small></h3></header><div class="rv-grade-body"><aside><p>${diligenceExplain[name]}</p><button>▦　檢視發現事項</button><a>▣　更多資訊</a>${info?'<p class="rv-info-note">* 此風險面向目前不影響安全評等</p>':''}</aside><main><h4>等級分布：<b>${count.toLocaleString()} ${unit}</b></h4><div class="rv-grade-chart">${vals.map((v,i)=>`<div><span style="height:${v?Math.max(v,1):0}%;background:${colors[i]}"><b>${v?`${v}%`:''}</b></span><strong>${cats[i]}</strong></div>`).join('')}</div></main></div>${name==='開放連接埠'?rvOpenPortsTable():''}${rvSoftwareExtras(name)}</article>`}
function rvOpenPortsTable(){const rows=[['80','6,464',0,'HTTP 及其他 5 項服務'],['443','4,766',88,'HTTPS 及其他 10 項服務'],['8443','585',12,'HTTP 及其他 5 項服務'],['2087','584',6,'HTTP 及其他 1 項服務'],['2082','583',0,'HTTP'],['2086','582',0,'HTTP'],['2083','581',8,'HTTP 及其他 2 項服務'],['53','543',2,'遞迴 DNS/tcp 及其他 2 項服務'],['8080','542',1,'HTTP 及其他 4 項服務'],['8880','516',0,'HTTP 及其他 1 項服務']];return `<section class="rv-open-ports"><h3>依開放連接埠統計主機</h3><input placeholder="搜尋…"><table><thead><tr><th>連接埠</th><th>主機總數　↓</th><th>等級分布</th><th>服務</th><th></th></tr></thead><tbody>${rows.map(([port,total,good,service])=>`<tr><td>${port}</td><td>${total}</td><td><i><span style="width:${good}%"></span></i></td><td>${service}</td><td>▦⌕</td></tr>`).join('')}</tbody></table><footer>顯示第 1–10 筆，共 97 筆 <span>‹　 <b>1</b> ／10　›</span></footer></section>`}
function rvCriticalTop10(){const rows=[['CVE-2019-10384',2451,'high'],['CVE-2023-22952',1248,'high'],['CVE-2023-22952',1209,'high'],['CVE-2021-44026',482,'critical'],['CVE-2024-23897',216,'critical'],['CVE-2024-23897',214,'critical'],['CVE-2024-23897',210,'critical'],['CVE-2019-17638',216,'critical'],['CVE-2019-10352',2451,'medium'],['CVE-2019-10384',223,'high']];return `<section class="rv-critical-top"><h4>截至今日影響最大的 10 項重大弱點管理發現事項</h4>${rows.map((r,i)=>`<div><a>${i+1}. ${r[0]}</a><i class="${r[2]}" style="width:${r[1]/2451*82}%"></i><b>${r[1].toLocaleString()} 天</b></div>`).join('')}<footer>持續時間（天）　　<span>低　　中　　高　　重大</span></footer></section>`}
function rvCriticalChart(g){const pts=[['9 月',170],['10 月',191],['11 月',181],['12 月',161],['1 月',126],['2 月',103],['3 月',134],['4 月',135],['5 月',179],['6 月',204],['7 月',203],['8 月',165],['9 月',128]];return `<article class="rv-critical"><header>${rvGrade(g)}<h3>重大弱點管理　<a>🔗</a></h3><b>↘ 後 20%</b></header><div><aside><p>此風險面向評估弱點平均需要多久完成改善或修補，並依弱點嚴重程度加權；越嚴重的弱點，對等級的影響越大。弱點是公開揭露的軟體漏洞或錯誤，攻擊者可能利用它們未經授權存取系統與資料；修補程式則是解決弱點並封閉該攻擊途徑的軟體更新。</p><p>圖表顯示各月份所有影響評等弱點的平均修補時間，以未修補的週數表示。弱點修補後仍會持續影響風險面向等級 90 天。</p><button>▦　檢視發現事項</button><a>▣　更多資訊</a></aside><main><h4>弱點修補成效</h4><svg viewBox="0 0 760 390"><g stroke="#d8e1e6" stroke-dasharray="5 4">${[45,112,179,246,313].map(y=>`<line x1="25" y1="${y}" x2="710" y2="${y}"/>`).join('')}</g>${pts.map(([m,v],i)=>{const x=70+i*51,y=330-(v-90)*1.7;return `<circle cx="${x}" cy="${y}" r="22" fill="#11191e"/><text x="${x-14}" y="365" font-size="12">${m}</text>`}).join('')}<g font-size="12" font-weight="700">${[225,200,175,150,125,100].map((v,i)=>`<text x="720" y="${49+i*54}">${v}</text>`).join('')}</g></svg><strong>修補時間（週）</strong></main></div>${rvCriticalTop10()}</article>`}
function rvDomainSquatting(){const matrix=[['網路釣魚',452,37,15,true],['新增字元',153,22,7],['相似字形',247,3,7],['連字號',47,2,0],['頂級網域變體',5,10,1],['位元翻轉',238,8,17,true],['位元仿冒',238,8,17],['拼字錯誤',870,78,38,true],['插入字元',449,16,0],['遺漏字元',41,6,5],['重複字元',33,0,0],['替換字元',233,16,19],['子網域',14,28,7],['字元對調',42,1,1]],domains='abcdefghij'.split('').map(x=>`frontstore${x}.us`);return `<article class="rv-domain"><header>${rvGrade('N/A')}<h3>網域仿冒**　<a>🔗</a></h3></header><p>網域仿冒會報告與組織所擁有網域名稱相似的已註冊網域。攻擊者可能利用相似網域提供惡意軟體，誘使輸入錯誤網址的訪客進入，或讓收件者誤開惡意附件。</p><a>▣　更多資訊</a><p>** 資訊型風險面向（永遠不影響安全評等）</p><label class="rv-domain-select">網域仿冒結果：<select><option>所有網域</option></select></label><section class="rv-domain-overview"><h4>總覽</h4><aside><b>1,753 筆結果</b><p>拼字錯誤<strong>56.2%　<small>986 筆</small></strong></p><p>網路釣魚<strong>28.8%　<small>504 筆</small></strong></p><p>位元翻轉<strong>15.0%　<small>263 筆</small></strong></p></aside><main><div><button class="active">仿冒類型</button><button>註冊者</button></div><div class="rv-domain-bars">${[['未註冊',452,238,870],['第三方',37,8,78],['其他公司',15,17,38]].map(([n,a,b,c])=>`<div><i style="height:${a/9}px"></i><i style="height:${b/3}px"></i><i style="height:${c/10}px"></i><b>${n}</b></div>`).join('')}</div></main></section><details class="rv-domain-details"><summary>所有網域的結果矩陣</summary><table><thead><tr><th></th><th>未註冊</th><th>第三方</th><th>其他公司</th></tr></thead><tbody>${matrix.map(r=>`<tr class="${r[4]?'group':''}"><td>${r[4]?'−　':''}${r[0]}</td><td>${r[1]}</td><td>${r[2]}</td><td>${r[3]}</td></tr>`).join('')}</tbody></table></details><details class="rv-domain-details" open><summary>所有網域的結果</summary><div class="rv-domain-filters"><button>所有仿冒類型　⌄</button><button>所有技術　⌄</button><button>所有註冊者　⌄</button><input placeholder="搜尋"><button>↓</button></div><table><thead><tr><th>仿冒類型</th><th>技術</th><th>註冊者</th><th>網域變體</th><th></th></tr></thead><tbody>${domains.map(d=>`<tr><td>網路釣魚</td><td>新增字元</td><td>未註冊</td><td>${d}</td><td>ⓘ</td></tr>`).join('')}</tbody></table><footer>顯示第 1–10 筆，共 1,753 筆 <span>‹　<b>1</b> ／176　›</span></footer></details></article>`}
function rvFileSharing(){const cats=[['應用程式',2,'#dda91e'],['書籍',0,'#dda91e'],['遊戲',0,'#dda91e'],['電影',19,'#07517f'],['音樂',0,'#07517f'],['電視',0,'#07517f'],['其他',7,'#294358']];return `<article class="rv-file"><header>${rvGrade('D')}<h3>檔案分享　<a>🔗</a></h3><b>↘ 後 30%</b></header><div><aside><p>檔案分享是媒體與軟體的交換，可透過集中式伺服器（檔案傳輸通訊協定、電子郵件、即時通訊）、分散式雲端儲存服務，或 BitTorrent、Gnutella 等直接點對點管道進行。Bitsight 僅追蹤在公司基礎設施上觀察到的 BitTorrent 檔案分享，並記錄書籍、音樂、電影、電視節目與應用程式等檔案的分享活動。</p><button>▦　檢視發現事項</button><a>▣　更多資訊</a></aside><main><h4>過去 60 天的檔案分享：28 個事件</h4><p>觀察到 6 個不重複 IP</p><div class="rv-file-chart">${cats.map(([n,v,c])=>`<div><span style="height:${v/30*88}%;background:${c}">${v||''}</span><b>${n}</b></div>`).join('')}</div></main></div></article>`}
function rvCredentials(){const rows=[['2026/09/21','2026/08/27','Manchester Airports Group','a.com','22'],['2026/09/17','2026/08/20','WorkL','a.com','1'],['2026/09/04','2026/08/22','Golf Canada','a.com','22'],['2026/09/03','2026/08/24','NIUS','a.com','22'],['2026/09/01','2026/08/13','Carhartt, Inc.','a.com','22'],['2026/08/28','2026/08/20','Oz Hair & Beauty','a.com','2'],['2026/08/24','2026/08/19','Fanlore','a.com','22'],['2026/08/14','2026/07/22','RevolutionParts','a.com','32'],['2026/08/07','2026/07/23','SplitVPN','a.com','1'],['2026/07/28','2026/05/07','Burger King Russia','a.com','1']];return `<article class="rv-credentials"><header>${rvGrade('N/A')}<h3>外洩憑證**　<a>🔗</a></h3></header><section class="rv-premium"><h4>全新！身分情報：進階版外洩憑證</h4><div class="rv-premium-grid"><div class="rv-premium-copy"><p><b>身分情報</b>平均可偵測多 4 倍的憑證，並支援密碼政策篩選、電子郵件排除、與身分提供者（IdP）建立關聯等功能。</p><p>身分情報也包含<b>待售存取權</b>。您可以追蹤初始存取代理人（IAB）市場上販售的帳戶，並在遭入侵資產被利用前購買這些資產。</p><button>深入了解身分情報進階版</button></div><table><thead><tr><th></th><th>標準版</th><th>進階版</th></tr></thead><tbody><tr><td>最近 7 天偵測</td><td>23</td><td>227,474</td></tr><tr><td>最近一年偵測</td><td>19,330</td><td>5,092,591</td></tr><tr><td>最近一年待售存取權</td><td>－</td><td>330</td></tr></tbody></table></div></section><h4>外洩憑證 <span>標準版</span></h4><p class="rv-credentials-note">外洩憑證風險面向顯示公司員工的資訊是否因公開揭露的資料外洩而遭洩漏。外洩憑證屬於資訊型風險面向，不會影響公司的安全評等。許多網站不會驗證電子郵件地址，因此很難確認特定外洩紀錄確實與公司員工有關。同樣地，Bitsight 不會透過嘗試使用外洩網站中的使用者名稱和密碼登入來測試外洩憑證是否有效，以維護企業信心與信任。</p><p class="rv-credentials-note">憑證下載檔案包含一個「次數」欄位，顯示每筆不重複資料（例如不同密碼）在資料外洩中出現的次數；完整詳細資料可於身分情報中取得。</p><a>▣　更多資訊</a><p>** 資訊型風險面向（永遠不影響安全評等）</p><section class="rv-events"><h4>觀察到的事件</h4><input placeholder="搜尋…"><button>↓ 下載憑證</button><table><thead><tr><th>觀察日期 ↓</th><th>外洩日期</th><th>遭入侵網站</th><th>網域</th><th>紀錄</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}<td>⌕</td></tr>`).join('')}</tbody></table><footer>顯示第 1–10 筆，共 752 筆 <span>‹　<b>1</b> ／76　›</span></footer></section></article>`}
function rvPublicDisclosures(){return `<div class="rv-public-intro"><h3>公開揭露</h3><p>公開揭露事件提供資料外洩、一般資安事件，以及其他可能涉及不當存取公司資料之揭露的資訊。</p><p>只有此類別中的特定事件會影響公司的安全評等，而且只有在事件實際發生時才會產生影響，不會像其他風險面向一樣占有固定的評等權重。</p></div><article class="rv-public"><header>${rvGrade('A')}<h3>資安事件／資料外洩　<a>🔗</a></h3><b>↗ 前 10%</b></header><section><aside><h4>資料外洩</h4><p>資料外洩是公開揭露的未授權存取事件，通常涉及資料遺失或竊取。這類事件會依多項因素評級，包括遺失或暴露的資料紀錄數量。</p><p>注意：資料外洩事件發生時會對安全評等造成負面影響，影響採 120 天半衰期計算。例如，嚴重資料外洩在 18 個月後的剩餘影響將低於 20 分，中度資料外洩則低於 10 分。</p><a>▣　更多資訊</a></aside><table><thead><tr><th>公開發現日期</th><th>生效日期</th><th>嚴重程度</th><th>類別</th><th></th></tr></thead><tbody><tr><td>2021-09-01</td><td>2021-09-17</td><td>中度</td><td>勒索軟體</td><td>◉</td></tr></tbody></table></section><section><aside><h4>一般資安事件</h4><p>一般資安事件涵蓋與公司資料遭不當存取相關的多種事件，嚴重程度高於其他揭露。部分類別會影響評等，其他類別僅供參考，不影響評等。這些事件會依多項因素評級，包括遺失或暴露的資料紀錄數量。</p><p>注意：會影響評等的一般資安事件只有在實際發生時才會對安全評等產生負面影響，並採 120 天半衰期計算。例如，最嚴重事件在 18 個月後的剩餘影響將低於 20 分，中度事件則低於 10 分。</p><a>▣　更多資訊</a></aside><div class="rv-empty">▦⌕<br>目前沒有影響此風險面向的事件。</div></section><section><aside><h4>其他揭露*</h4><p>其他揭露是公開揭露中嚴重程度最低的一組事件。此類別用於透過公開資訊或其他來源得知，且判定對安全態勢影響極小的事件。所有其他揭露類別都僅供參考，不會影響安全評等。</p><a>▣　更多資訊</a><p>* 此風險面向目前不影響安全評等</p></aside><table><thead><tr><th>公開發現日期</th><th>生效日期</th><th>嚴重程度</th><th>類別</th><th>來源</th><th></th></tr></thead><tbody><tr><td>2024-09-01</td><td>2024-09-03</td><td>資訊型</td><td>DNS 發現事項</td><td>直接</td><td>◉</td></tr><tr><td>2021-01-18</td><td>2021-01-18</td><td>資訊型</td><td>其他揭露</td><td>直接</td><td>◉</td></tr></tbody></table></section></article>`}
function rvFullGroup(group,items,start=0){if(group==='使用者行為')return `<section class="panel rv2-group"><h2>使用者行為</h2><p>使用者行為會檢視可能將惡意軟體帶入公司的檔案分享活動，例如下載遭入侵的檔案。</p>${rvFileSharing()}${rvCredentials()}</section>`;if(group==='公開揭露')return `<section class="panel rv2-group">${rvPublicDisclosures()}</section>`;const special=['Web 應用程式安全','不安全系統','伺服器軟體','桌面軟體','行動軟體','DNSSEC*','Web 應用程式標頭*'];return `<section class="panel rv2-group"><h2>${group}</h2>${group==='盡職調查'?rvDiligenceOverview():''}${items.map(([name,w,g],i)=>group==='盡職調查'&&(i<6||special.includes(name))?rvGradeDistribution(name,g):group==='盡職調查'&&name==='重大弱點管理'?rvCriticalChart(g):group==='盡職調查'&&name==='網域仿冒**'?rvDomainSquatting():rvFullVector(name,g,start+i)).join('')}</section>`}
function spmRiskVectorsV2(){const compromised=riskGroups[0][2],diligence=riskGroups[1][2];return `${pagebar('Saperix, Inc. 風險面向總覽','<button class="outline" data-modal="reports">報表　▧</button><button class="outline" data-modal="spm-action">動作　⌄</button>')}<div class="rv2-layout">${rvNav()}<main class="rv2-main">${rvOverview()}<section class="panel rv2-compromised"><h2>受駭系統</h2><p>受駭系統是組織網路中出現惡意或非預期軟體跡象的裝置或機器。這些感染可能中斷日常營運並提高組織遭資料外洩的風險。</p><p>受駭系統會依惡意程式數量與類型、嚴重程度及持續時間進行評估，並為每項風險面向計算整體字母等級。</p><p>例如，若組織在短時間內出現大量殭屍網路感染，或少數感染持續數月，其殭屍網路感染等級可能會是 F。</p>${rvBubbleChart()}${compromised.map(([n])=>rvCompromisedVector(n)).join('')}</section>${rvFullGroup('盡職調查',diligence,5)}${rvFullGroup('使用者行為',riskGroups[2][2],20)}${rvFullGroup('公開揭露',riskGroups[3][2],22)}</main></div>`}
