function spmSubsidiaries(){const months=['2026 年 4 月','2026 年 5 月','2026 年 6 月','2026 年 7 月','2026 年 8 月','2026 年 9 月','今天'];return `${pagebar('子公司')}<div class="content subsidiaries-page"><section class="panel subsidiary-panel"><div class="subsidiary-tools"><div><h3>組織歷史分布</h3><small>上次更新：2026/09/21</small></div><label class="switch"><input type="checkbox" id="allSubsidiaries"> 顯示所有子公司</label><select><option>Bitsight 評等</option></select><span>縮放</span><button class="active" data-sub-zoom="6m">6 個月</button><button data-sub-zoom="1y">1 年</button><span class="spacer"></span><button data-toast="示範熱圖已準備匯出">匯出　↓</button></div><div class="subsidiary-heatmap"><div class="heat-head">${months.map(x=>`<b>${x}</b>`).join('')}<b></b></div>${subsidiaryRows.map((r,i)=>`<div class="heat-row" data-subsidiary-row="${i}">${r.slice(1).map(v=>`<span style="background:${ratingHeat(v)}">${v}</span>`).join('')}<strong>▥　${r[0]}</strong></div>`).join('')}</div><div class="heat-legend"><p><b>基礎</b><i style="background:#57241f"></i>&lt; 410 <i style="background:#b84034"></i>420–520 <i style="background:#cf5140"></i>530–630</p><p><b>中階</b><i style="background:#c79c3d"></i>640–670 <i style="background:#d5ad48"></i>680–700 <i style="background:#ebca5d"></i>710–730</p><p><b>進階</b><i style="background:#4e9565"></i>740–760 <i style="background:#34734e"></i>770–790 <i style="background:#184c38"></i>&gt; 800</p></div><button class="subsidiary-cta" data-nav="spm-subsidiary-improvement">檢視子公司改善</button></section></div>`}
function spmBreach(){const fs=['嚴重程度','事件類型','評等影響','來源類型','國家／地區','產業','公司','日期','攻擊者','進階持續性威脅（APT）','CVE','受影響產品'];return `${pagebar('資料外洩情報','<button class="outline" data-toast="示範資料已準備下載">↓　下載 CSV</button>')}<div class="content breach-page"><aside class="breach-filters"><h3>▽ 篩選　‹</h3><input placeholder="搜尋篩選條件…">${fs.map(x=>`<button data-filter="${x}">${x}<span>⌄</span></button>`).join('')}</aside><section class="panel breach-results"><div class="breach-empty">▽</div></section></div>`}
function spmBadge(){const code='&lt;div id="bitsight-badge"&gt;&lt;/div&gt;\n&lt;script&gt;取得並顯示 Bitsight 評等徽章&lt;/script&gt;';return `${pagebar('Bitsight 徽章')}<div class="content badge-page"><section class="panel badge-panel"><label class="badge-enable"><input type="checkbox" checked> <span>啟用評等分享</span></label><p>建立可嵌入的元件來展示您的評等，並說明評等的意義及重要性。<a>深入了解</a></p><hr><div class="badge-tabs"><b>選項</b><button class="active" data-badge-tab="badge">徽章</button><button data-badge-tab="landing">到達頁面</button></div><div class="badge-builder"><div class="badge-preview"><span class="measure-v">300px</span><div class="badge-circle"><div class="badge-logo">BITSIGHT</div><strong>420</strong><small>安全評等 · 基礎</small></div><span class="measure-h">300px</span></div><aside><h4>版型</h4><label><input type="radio" name="layout" checked> 徽章</label><label><input type="radio" name="layout"> 窄版</label><label><input type="radio" name="layout"> 寬版</label><h4>尺寸</h4><label><input type="radio" name="size" checked> 大</label><label><input type="radio" name="size"> 中</label><label><input type="radio" name="size"> 小</label><hr><h4>嵌入碼</h4><pre>${code}</pre><button data-toast="已複製示範嵌入碼">複製嵌入碼</button></aside></div><section class="badge-config"><h3>徽章設定</h3><div><h4>我的評等</h4><label><input type="radio" checked> 90 天平均</label><label><input type="radio"> 目前評等</label></div><div><h4>產業比較</h4><label><input type="checkbox"> 顯示產業平均</label></div><div><h4>允許的網域</h4><p>預設僅能在 saperix.com 使用徽章嵌入碼。可在下方加入其他完整網址。</p><input placeholder="https://example.com"><button disabled>儲存變更</button></div></section></section></div>`}
function spmCompanyContent(html,kind=''){let out=html.replaceAll('範例商業銀行','Saperix, Inc.').replaceAll('範例物業管理集團','Saperix, Inc.').replaceAll('範例金融控股','Saperix Corporate').replaceAll('範例資訊服務','Saperix Lab');if(kind==='threat')out=out.replaceAll('威脅洞察：','弱點偵測：').replaceAll('主動偵測並回應新興威脅','偵測暴露於網際網路的重大弱點');return out}
